use std::cmp::Ordering;

fn remove_duplicates(nums: &Vec<i32>) -> usize {
    let n = nums.len();
    if n == 0 {
        return 0;
    }

    let mut count: usize = 1;
    let mut prev = nums[0];

    for &x in nums.iter().skip(1) {
        if x != prev {
            count += 1;
            prev = x;
        }
    }

    debug_assert!(count <= n);
    count
}